class FFT_Factorize(ctypes.Structure):
    _fields_ = [('n', ctypes.c_int), ('prime_factors', ctypes.POINTER(ctypes.c_int))]

def fft_factorize(n, subtransforms):
    libgsl = ctypes.pyobject()
    libgsl.gsl_factorize.restype = ctypes.POINTER(FFT_Factorize)
    libgsl.gsl_factorize.argtypes = [ctypes.c_int]
    result = libgsl.gsl_factorize(n)
    prime_factors = array('i', [0] * (result.contents.n + 1))
    prime_factors[:result.contents.n+1] = array('i', list(range(2, int(result.contents.n**0.5) + 1)))
    for i in range(2, int(result.contents.n**0.5) + 1):
        if prime_factors[i]:
            j = i * i
            while j <= result.contents.n:
                if j % i == 0 and not prime_factors[j // i]:
                    prime_factors[j] = 1
                    j += i
                else:
                    break
    return {'prime_factors': list(prime_factors), 'num_of_prime_factors': len([x for x in prime_factors if x])}

