import numpy as np
import ctypes
from ctypes import c_int, c_double, POINTER

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols

    @staticmethod
    def numpy_to_gsl_matrix(np_array):
        if not isinstance(np_array, np.ndarray) or len(np_array.shape) != 2:
            raise ValueError("Input must be a 2D NumPy array")
        rows = c_int(len(np_array))
        cols = c_int(len(np_array[0]))
        return ctypes.c_double * (rows * cols)(*(np_array.flatten()))

    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix):
        if not isinstance(gsl_matrix, POINTER(ctypes.c_double)):
            raise ValueError("Input must be a GSL matrix")
        rows = c_int.g_object_get_type(gsl_matrix).contents.shape[0]
        cols = c_int.g_object_get_type(gsl_matrix).contents.shape[1]
        return np.array(gsl_matrix[:rows * cols]).reshape((rows, cols))

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def compute_covariance(jacobian, epsrel):
    if not isinstance(jacobian, GSLMatrix) or jacobian.rows == 0:
        raise ValueError("Input Jacobian must be a valid GSL matrix")
    if not isinstance(epsrel, (int, float)) or epsrel < 0.0:
        raise ValueError("Relative error tolerance must be a positive float")

    result = gslcblas.gsl_multifit_covar(jacobian.numpy_to_gsl_matrix(), c_double(epsrel))
    return GSLMatrix(result.shape[0], result.shape[1]).gsl_matrix_to_numpy()

def main():
