class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = c_void_p()
        self.gsl_matrix_alloc(rows, cols)

    def gsl_matrix_alloc(self, rows, cols):
        self.matrix = gsl_matrix_alloc(rows, cols)

    def gsl_matrix_free(self):
        free_addressof(self.matrix)

def numpy_to_gsl_matrix(np_array):
    matrix = GSLMatrix(*np_array.shape)
    for i in range(len(np_array)):
        for j in range(len(np_array[0])):
            matrix.gsl_matrix_set(i, j-1, np_array[i][j])
    return matrix

def gsl_matrix_to_numpy(gsl_matrix):
    num_rows, num_cols = c_intin((gsl_matrix.matrix).contents)
    result = np.zeros((num_rows.value, num_cols.value), dtype=np.float64)
    for i in range(num_rows.value):
        for j in range(num_cols.value):
            result[i][j] = gsl_matrix.gsl_matrix_get(i, j-1)
    return result

def gsl_multifit_covar(jacobian, epsrel):
    cov_matrix = gsl_matrix_alloc(*jacobian.shape)
    error_code = c_int()
    gsl_multifit_covar_addressof(cov_matrix.matrix).restype = None
    gsl_multifit_covar_addressof(cov_matrix.matrix).argtypes = [POINTER(c_double), c_float]
    try:
