        return self.array.tolist()

def numpy_to_gsl_matrix(np_array):
    rows, cols = np_array.shape
    mat = gsl_matrix(np_array)
    mat.set_size(rows, cols)
    return mat

def numpy_to_gsl_vector(np_array):
    vec = gsl_vector(np_array)
    return vec

def compute_gensymm_eigenvalues(A, B):
    np_A = A.flatten().copy()
    np_B = B.flatten().copy()
    matA = numpy_to_gsl_matrix(np_A.reshape(A.shape[0], -1))
    matB = numpy_to_gsl_matrix(np_B.reshape(B.shape[0], -1))
    work = gsl.eigen.gensymm_workspace()
    eigenvalues = (c_double * A.shape[0])()
    result = gsl.eigen.gensymm_eigenvalues(matA.get_data(), matB.get_data(), eigenvalues, work)
    if result < 0:
        raise ValueError('Error computing eigenvalues')
    return np.array(eigenvalues)

