class GSLFunction:
    def __init__(self, f):
        self.f = f
    def __call__(self, x):
        return self.f(x)

def f1(x):
    return np.sin(x) + 2*x

def f2(x):
    return np.exp(-x**2)

def f3(x):
    return x**2 - 10*np.sin(2*x)

def integrate(function, a, b, epsabs, epsrel):
    # Create an instance of GSLFunction
    g = GSLFunction(function)

    # Initialize the GSL integration variables
    result = ctypes.c_double(0.0)
    abserr = ctypes.c_double(0.0)
    error = ctypes.c_double(0.0)
    last_error = ctypes.c_int(0)

    # Set the GSL function evaluation limits
    gsl.gsl_integration_qng.restype = None
    gsl.gsl_integration_qng.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int)]

    # Perform the numerical integration
    error_code = gsl.gsl_integration_qng(g, a, b, epsabs, epsrel, byref(result), byref(abserr), byref(error), byref(last_error))
    if error_code != 0:
        print(f\"Error code: {error_code}\")

