gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

class RNG:
    def __init__(self):
        self.rng = gsl.gaussian_rnd_t()

    def rand(self, mean, sigma):
        return (gsl.gaussian_rnd(mean/sigma, 1.0/sigma) + mean)

def compute_statistics(N, K, sigma, N_sigma):
    rng = RNG()
    seed(42)

    stats = np.zeros((N, 6))
    for i in range(N):
        if i < N_sigma[0]:
            val = gauss(0, sigma[0])
        elif i >= N_sigma[0] and i < N_sigma[1]:
            val = gauss(0, sigma[1])
        else:
            val = gauss(0, sigma[-1])

        stats[i, 0] = val
        for j in range(i+1):
            stats[j, 1:] = gsl.gsl_stats_move(N, K, j, rng.rng, [val], stats[:j+1, :5])

    return stats

def assert_test(stats, N, K):
    np.testing.assert_equal(np.round(stats[:,0], 2), np.round(np.random.normal(0, 1, N), 2))
    for i in range(N):
        if i < N_sigma[0]:
            sig = sigma[0]
        elif i >= N_sigma[0] and i < N_sigma[1]:
            sig = sigma[1]
        else:
            sig = sigma[-1]
        np.testing.assert_allclose(np.abs(stats[i, 1:]), sig, atol=0.05)

if __name__ == "__main__":
    N = 100
    K = 10
    sigma = [0.5, 1.0, 2.0]
    N_sigma = [20, 50]

    stats = compute_statistics(N, K, sigma, N_sigma)
