class GSLVector(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)), ('size', ctypes.c_size_t)]
    def __init__(self, data=None, size=0):
        if data is None:
            self.data = ctypes.POINTER(ctypes.c_double)(ctypes.c_size_t(0))
        else:
            self.data = ctypes.cast(array(data).ctypes.data_as(ctypes.POINTER(ctypes.c_double)), ctypes.POINTER(ctypes.c_double))
        self.size = size

    def __del__(self):
        if self.data is not None and self.size > 0:
            ctypes.free(self.data)

def householder_transform(input_vector):
    gsl.gsl_linalg_householder_transform.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.POINTER(ctypes.c_double)]
gsl.gsl_linalg_householder_transform.restype = None

    tau = ctypes.c_double(0)
    result_vector = GSLVector(array(input_vector).ctypes.data_as(ctypes.POINTER(ctypes.c_double)), len(input_vector))
    gsl.gsl_linalg_householder_transform(result_vector.data, ctypes.pointer(tau), len(input_vector), result_vector.data)

    return {'tau': tau.value, 'vector': [x for x in array(result_vector.data)[:result_vector.size]]}

