class gsl_matrix:
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)),
                ('size1', ctypes.c_size_t),
                ('size2', ctypes.c_size_t)]

class gsl_vector:
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)),
                ('size', ctypes.c_size_t)]

def matrix_to_gsl(matrix):
    data = (ctypes.c_double * (matrix[0] * len(matrix)))()
    for i in range(len(matrix)):
        for j in range(matrix[0]):
            data[i*len(matrix[0]) + j] = matrix[i][j]
    return gsl_matrix(data, len(matrix), matrix[0])

def vector_to_gsl(vector):
    data = (ctypes.c_double * len(vector))()
    for i in range(len(vector)):
        data[i] = vector[i]
    return gsl_vector(data, len(vector))

def gsl_matrix_to_list(matrix):
    return [[matrix.data[i*matrix.size2 + j] for j in range(matrix.size1)] for i in range(matrix.size2)]

def gsl_vector_to_list(vector):
    return [vector.data[i] for i in range(vector.size)]

def ql_decomposition_and_unpack(A, tau):
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(tau)
    decomposition = gsl.linalg.QL_decomp(A_gsl, tau_gsl, None)
    unpacking = gsl.linalg.QL_unpack(decomposition, None, None)
    return gsl_matrix_to_list(unpacking[0]), gsl_vector_to_list(unpacking[1])

