free_control = gsl.odeiv2.free_control

def create_scaled_control(eps_abs, eps_rel, a_y, a_dydt, scale_abs, dim):
    control_ptr = ctypes.c_void_p()
    create_control.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double,
                               ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.c_int]
    create_control.restype = ctypes.c_void_p
    create_control(eps_abs, eps_rel, a_y, a_dydt, np.array(scale_abs).ctypes.data_as(ctypes.POINTER(ctypes.c_double)), dim)
    return control_ptr.value

